INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Gesetz zur IT-Sicherheit nur für große Firmen gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Betreiber betroffen"}, {"text": "Ja", "correct": false, "because": "Abhängig von Kritikalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Unternehmen laut einem IT-Sicherheitsgesetz?', 3, '[{"text": "Schutz kritischer Systeme", "correct": true, "because": "Vorgabe des IT-SIG"}, {"text": "Webdesign verbessern", "correct": false, "because": "Kein Fokus"}, {"text": "Hardware verkaufen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt ein Gesetz an kritische Infrastrukturen?', 5, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schutz vor Angriffen"}, {"text": "Meldung von Vorfällen", "correct": true, "because": "BSI informieren"}, {"text": "Risikoanalysen", "correct": true, "because": "Gefahren erkennen"}, {"text": "Farbanpassung", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das IT-SIG verlangt Sicherheitskonzepte. b) Es gilt nur für Banken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für viele Sektoren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Unternehmen nach einem Sicherheitsgesetz betreibe?', 4, '[{"text": "Risikomanagement", "correct": false, "because": "Pflicht im IT-SIG"}, {"text": "Vorfallmeldung", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Sicherheitsgesetz nur für Server gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst ganze Infrastruktur"}, {"text": "Ja", "correct": false, "because": "Breiter Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BSI in einem IT-Sicherheitsgesetz?', 3, '[{"text": "Überwachung", "correct": true, "because": "Kontrolliert Einhaltung"}, {"text": "Hardwarelieferant", "correct": false, "because": "Keine Funktion"}, {"text": "Designberater", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einhaltung eines Sicherheitsgesetzes?', 5, '[{"text": "Schutz vor Angriffen", "correct": true, "because": "Sicherheitsmaßnahmen"}, {"text": "Rechtliche Konformität", "correct": true, "because": "Gesetz erfüllt"}, {"text": "Vertrauen der Kunden", "correct": true, "because": "Sicherheitsimage"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) KRITIS-Betreiber betroffen sind und b) es nur für Hardware gilt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Sicherheitsgesetz umzusetzen?', 4, '[{"text": "Risikoanalysen", "correct": false, "because": "Pflicht im IT-SIG"}, {"text": "Schutzmaßnahmen", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jedes Unternehmen einen Sicherheitsbeauftragten haben?', 2, '[{"text": "Ja", "correct": true, "because": "Für KRITIS vorgeschrieben"}, {"text": "Nein", "correct": false, "because": "Pflicht bei Kritikalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sind bei einem Sicherheitsgesetz wichtig?', 4, '[{"text": "Vorfallmeldung", "correct": true, "because": "BSI informieren"}, {"text": "Technische Schutzmaßnahmen", "correct": true, "because": "Systeme sichern"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein IT-Sicherheitsgesetz nur für Software gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware betroffen"}, {"text": "Ja", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Einhaltung eines Sicherheitsgesetzes?', 3, '[{"text": "Schutz kritischer Systeme", "correct": true, "because": "Hauptziel IT-SIG"}, {"text": "Designverbesserung", "correct": false, "because": "Kein Fokus"}, {"text": "Kostensteigerung", "correct": false, "because": "Nebenwirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Vorfälle müssen gemeldet werden. b) Es gilt nur für Energie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Sektoren betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt eine Risikoanalyse im IT-SIG?', 4, '[{"text": "Gefahren erkennen", "correct": true, "because": "Pflicht zur Bewertung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das IT-SIG nur für Deutschland gilt?', 2, '[{"text": "Ja", "correct": true, "because": "Nationales Gesetz"}, {"text": "Nein", "correct": false, "because": "Deutsches Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Sicherheitsgesetz effektiv?', 5, '[{"text": "Risikomanagement", "correct": true, "because": "Bewertet Gefahren"}, {"text": "Schutzmaßnahmen", "correct": true, "because": "Sichert Systeme"}, {"text": "Vorfallmeldung", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt das IT-SIG für alle IT-Systeme?', 3, '[{"text": "Nein", "correct": true, "because": "Nur kritische Infrastrukturen"}, {"text": "Ja", "correct": false, "because": "Spezifische Betreiber"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem IT-Sicherheitsgesetz?', 4, '[{"text": "Krankenhaus sichert IT-Systeme", "correct": true, "because": "KRITIS-Bereich"}, {"text": "Webdesign erstellen", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]');
